import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
const root=new URL('../../..',import.meta.url).pathname.replace(/\/$/,'');
const deps=process.env.FORKLAUNCH_TEST_BETTER_AUTH_DEPENDENCIES;
const {betterAuthReference}=await import(pathToFileURL(root+'/cli/tests/fixtures/rust_better_auth_reference.mjs'));
const {betterAuth}=await import(pathToFileURL(deps+'/node_modules/better-auth/dist/index.mjs'));
const {organization}=await import(pathToFileURL(deps+'/node_modules/better-auth/dist/plugins/organization/index.mjs'));
const ref=await betterAuthReference(root);
const call=async(auth,path,body,cookie='')=>{const r=await auth.handler(new Request('http://localhost:3000/api/auth'+path,{method:body?'POST':'GET',headers:{origin:'http://localhost:3000','content-type':'application/json',cookie},...(body?{body:JSON.stringify(body)}:{})}));const text=await r.text();return {status:r.status,body:text?JSON.parse(text):null,cookie:r.headers.getSetCookie().map(x=>x.split(';')[0]).join('; ')};};
const signup=await call(ref.auth,'/sign-up/email',{name:'Owned',firstName:'Owned',lastName:'User',email:'org-policy@example.test',password:'owned-password'});assert.equal(signup.status,200);
const saved=structuredClone(ref.database),uid=signup.body.user.id,cookie=signup.cookie;
const secret=(await ref.auth.$context).secret;
const rows=[];
function setup(teams={},members=1){for(const key of Object.keys(ref.database))ref.database[key]=structuredClone(saved[key]);ref.database.user[0].emailVerified=true;
ref.database.user.push({...structuredClone(ref.database.user[0]),id:'target-user',email:'target-policy@example.test'});
ref.database.organization.push({id:'org-policy-existing',name:'Existing',slug:'existing',createdAt:new Date(),subscription:'free',status:'active'});
for(let i=0;i<members;i++)ref.database.member.push({id:'member-'+i,organizationId:'org-policy-existing',userId:i?('other-'+i):uid,role:i?'member':'owner',createdAt:new Date()});
ref.database.organizationRole.push({id:'owner-grant',organizationId:'org-policy-existing',role:'owner',permission:JSON.stringify({team:['create','delete','update'],member:['create','update'],invitation:['create']}),createdAt:new Date()});
const auth=betterAuth({...ref.config,secret,logger:{disabled:true},rateLimit:{enabled:false},plugins:ref.config.plugins.map(p=>p.id==='organization'?organization({...p.options,teams:{...p.options.teams,...teams}}):p)});return auth;}

function team(id='team-existing',count=0){ref.database.team.push({id,organizationId:'org-policy-existing',name:id,memberCount:count,createdAt:new Date()});}
for(const [name,policy,count,status] of [
 ['default',{},1,200],['zero-unlimited',{maximumTeams:0},1,200],['one-full',{maximumTeams:1},1,400],['two-space',{maximumTeams:2},1,200]
]){const auth=setup(policy);for(let i=0;i<count;i++)team('team-'+i);const out=await call(auth,'/organization/create-team',{organizationId:'org-policy-existing',name:'Next'},cookie);assert.equal(out.status,status,JSON.stringify({name,out}));rows.push({name,status:out.status,code:out.body?.code});}
for(const [enabled,count]of [[true,1],[false,0]]){const auth=setup({defaultTeam:{enabled},maximumTeams:0,maximumMembersPerTeam:0});const out=await call(auth,'/organization/create',{name:'Created',slug:'created'},cookie);assert.equal(out.status,200);assert.equal(ref.database.team.length,count);assert.equal(ref.database.teamMember.length,count);rows.push({name:'default-team-'+enabled,status:out.status,teams:count,activeTeam:ref.database.session[0].activeTeamId});}
for(const [allow,status]of [[false,400],[true,200]]){const auth=setup({allowRemovingAllTeams:allow});team();const out=await call(auth,'/organization/remove-team',{organizationId:'org-policy-existing',teamId:'team-existing'},cookie);assert.equal(out.status,status,JSON.stringify(out));rows.push({name:'remove-last-'+allow,status:out.status,code:out.body?.code});}
for(const [name,limit,duplicate,status]of [['default',undefined,false,200],['zero',0,false,403],['one',1,false,200],['duplicate-zero',0,true,200]]){const auth=setup(limit===undefined?{}:{maximumMembersPerTeam:limit});team();ref.database.member.push({id:'target-member',organizationId:'org-policy-existing',userId:'target-user',role:'member',createdAt:new Date()});if(duplicate)ref.database.teamMember.push({id:'existing-pair',teamId:'team-existing',userId:'target-user',createdAt:new Date()});const out=await call(auth,'/organization/add-team-member',{organizationId:'org-policy-existing',teamId:'team-existing',userId:'target-user'},cookie);assert.equal(out.status,status,JSON.stringify({name,out}));rows.push({name:'add-'+name,status:out.status,code:out.body?.code,count:ref.database.team[0].memberCount});}

for(const limit of [0,1]){const auth=setup({maximumMembersPerTeam:limit});team();const r=await auth.api.addMember({body:{organizationId:'org-policy-existing',userId:'target-user',role:'member',teamId:'team-existing'},asResponse:true});const out=await r.json();assert.equal(r.status,limit?200:403,JSON.stringify(out));assert.equal(ref.database.member.filter(m=>m.userId==='target-user').length,limit?1:0);rows.push({name:'add-org-member-'+limit,status:r.status,code:out.code});}
for(const [name,count,stored,limit,status] of [['empty',0,0,0,403],['space',0,9,1,200],['full',1,0,1,403]]){const auth=setup({maximumMembersPerTeam:limit});team('team-existing',stored);for(let i=0;i<count;i++)ref.database.teamMember.push({id:'pair-'+i,teamId:'team-existing',userId:'other-'+i,createdAt:new Date()});const out=await call(auth,'/organization/invite-member',{organizationId:'org-policy-existing',email:'new-team@example.test',role:'member',teamId:'team-existing'},cookie);assert.equal(out.status,status,JSON.stringify({name,out}));rows.push({name:'invite-'+name,status:out.status,code:out.body?.code});}
for(const limit of [0,1]){const auth=setup({maximumMembersPerTeam:limit});team();ref.database.member[0].userId='target-user';ref.database.invitation.push({id:'accept-team',organizationId:'org-policy-existing',email:'org-policy@example.test',role:'member',inviterId:'target-user',teamId:'team-existing',status:'pending',expiresAt:new Date(Date.now()+3600000),createdAt:new Date()});const out=await call(auth,'/organization/accept-invitation',{invitationId:'accept-team'},cookie);assert.equal(out.status,limit?200:403,JSON.stringify(out));assert.equal(ref.database.invitation[0].status,limit?'accepted':'pending');rows.push({name:'accept-'+limit,status:out.status,code:out.body?.code});}
for(const count of [100,101]){const auth=setup({maximumTeams:101});for(let i=0;i<count;i++)team('team-'+i);const out=await call(auth,'/organization/create-team',{organizationId:'org-policy-existing',name:'Window'},cookie);assert.equal(out.status,200);rows.push({name:'team-window-'+count,status:out.status});}
{const auth=setup({maximumMembersPerTeam:101});team();for(let i=0;i<101;i++)ref.database.teamMember.push({id:'pair-'+i,teamId:'team-existing',userId:'other-'+i,createdAt:new Date()});const out=await call(auth,'/organization/invite-member',{organizationId:'org-policy-existing',email:'window-team@example.test',role:'member',teamId:'team-existing'},cookie);assert.equal(out.status,200);rows.push({name:'invite-window101',status:out.status,code:out.body?.code});}
for(const keep of [false,true]){const auth=setup({defaultTeam:{enabled:false}});ref.database.session[0].activeTeamId='old-active';ref.database.session[0].activeOrganizationId='org-policy-existing';const out=await call(auth,'/organization/create',{name:'NoDefault',slug:'no-default',keepCurrentActiveOrganization:keep},cookie);assert.equal(out.status,200);assert.equal(ref.database.session[0].activeTeamId,'old-active');assert.equal(ref.database.session[0].activeOrganizationId,keep?'org-policy-existing':out.body.id);rows.push({name:'preserve-active-'+keep,status:out.status});}
{const auth=setup({maximumMembersPerTeam:0});const out=await call(auth,'/organization/invite-member',{organizationId:'org-policy-existing',email:'empty-team@example.test',role:'member',teamId:''},cookie);assert.equal(out.status,200);rows.push({name:'empty-team-no-limit-check',status:out.status});}
for(const [name,actual,stored,expected]of [['undercount',1,0,403],['overcount',0,9,403]]){const auth=setup({maximumMembersPerTeam:1});team('team-existing',stored);ref.database.member.push({id:'target-member',organizationId:'org-policy-existing',userId:'target-user',role:'member',createdAt:new Date()});for(let i=0;i<actual;i++)ref.database.teamMember.push({id:'pair-'+i,teamId:'team-existing',userId:'other-'+i,createdAt:new Date()});const out=await call(auth,'/organization/add-team-member',{organizationId:'org-policy-existing',teamId:'team-existing',userId:'target-user'},cookie);assert.equal(out.status,expected);rows.push({name:'seat-'+name,status:out.status,stored:ref.database.team[0].memberCount});}
console.log('PASS team policy actual'+rows.length,JSON.stringify(rows));
